def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_C = 0
    opp_D = 0
    my_C = 0
    my_D = 0
    for h in history:
        if h[1] == 'C':
            opp_C += 1
        else:
            opp_D += 1
        if h[0] == 'C':
            my_C += 1
        else:
            my_D += 1

    last_my, last_opp = history[-1]

    if n >= 99:
        return 'D'
    if n == 98:
        if opp_D <= 2 or opp_C >= n - 2:
            return 'D'
        return 'C'

    if opp_C == 0:
        return 'D'

    if opp_D == 0:
        if my_D == 0:
            if n >= 5:
                return 'D'
            return 'C'
        else:
            if last_opp == 'C':
                return 'D'
            return 'C'

    if my_D > opp_D + 3 and opp_C > opp_D * 3:
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            return 'C'
        if n >= 2 and history[-2][0] == 'D':
            return 'C'
        return 'D'
    else:
        if last_my == 'D':
            return 'C'
        return 'C'
